package com.easybikerentals.controller;
import com.easybikerentals.entity.Booking; import com.easybikerentals.repository.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.math.BigDecimal; import java.time.*; import java.util.List;
@RestController @RequestMapping("/api/bookings") public class BookingController {
 private final BookingRepository bookings; private final UserRepository users; private final PaymentRepository payments; public BookingController(BookingRepository b,BikeRepository bikes,UserRepository u,PaymentRepository p){bookings=b;users=u;payments=p;}
 record Request(@NotNull Long bikeId,@NotNull LocalDateTime pickupAt,@NotNull LocalDateTime returnAt,@NotBlank String pickupLocation,@NotBlank String returnLocation,@NotBlank String licenseNumber){}
 private String email(){return SecurityContextHolder.getContext().getAuthentication().getName();}
 @GetMapping public List<Booking> mine(){var a=SecurityContextHolder.getContext().getAuthentication();var result=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"))?bookings.findAllByOrderByCreatedAtDesc():bookings.findByCustomerIdOrderByCreatedAtDesc(users.findByEmail(email()).orElseThrow().id);result.forEach(b->payments.findFirstByBooking_IdOrderByPaidAtDesc(b.id).ifPresent(p->{b.paymentStatus=p.status;b.paymentReference=p.transactionReference;}));return result;}
 @PostMapping @Transactional public Booking create(@Valid @RequestBody Request r){if(!r.returnAt().isAfter(r.pickupAt())||r.pickupAt().isBefore(LocalDateTime.now()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a valid future rental period");var bike=bookings.lockBike(r.bikeId());if(bike==null||!bike.active)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Bike not found");if(bookings.overlaps(bike.id,r.pickupAt(),r.returnAt()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Bike is already booked for those dates");long hours=Math.max(1,Duration.between(r.pickupAt(),r.returnAt()).toHours());long days=(hours+23)/24;var amount=bike.pricePerDay.multiply(BigDecimal.valueOf(days));var b=new Booking();b.bookingCode="EBR-"+java.util.UUID.randomUUID().toString().substring(0,8).toUpperCase();b.customer=users.findByEmail(email()).orElseThrow();b.bike=bike;b.pickupAt=r.pickupAt();b.returnAt=r.returnAt();b.pickupLocation=r.pickupLocation();b.returnLocation=r.returnLocation();b.licenseNumber=r.licenseNumber();b.totalAmount=amount.add(bike.securityDeposit==null?BigDecimal.ZERO:bike.securityDeposit);return bookings.save(b);}
 @DeleteMapping("/{id}") @Transactional public Booking cancel(@PathVariable Long id){var b=bookings.findById(id).orElseThrow();if(!b.customer.email.equals(email()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(!b.status.equals("PENDING")&&!b.status.equals("CONFIRMED"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Booking can no longer be cancelled");b.status="CANCELLED";return bookings.save(b);}
 @PatchMapping("/{id}/status") @Transactional public Booking status(@PathVariable Long id,@RequestParam String value){if(!SecurityContextHolder.getContext().getAuthentication().getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_ADMIN")))throw new ResponseStatusException(HttpStatus.FORBIDDEN);var b=bookings.findById(id).orElseThrow();if(!List.of("CONFIRMED","REJECTED","PICKED_UP","COMPLETED","CANCELLED").contains(value))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid status");b.status=value;return bookings.save(b);}
}
